//! `async-client` feature, so this lives outside both to avoid two copies
//! drifting out of sync.
#![cfg(test)]

use std::collections::HashMap;
use std::sync::Mutex;

use crate::feature_flag_evaluations::{FeatureFlagEvaluationsHost, FlagCalledEventParams};
use crate::feature_flags::{FeatureFlag, FeatureFlagCondition, FeatureFlagFilters};
use crate::local_evaluation::LocalEvaluationResponse;

#[derive(Default)]
pub(super) struct RecordingHost {
    pub(super) captured: Mutex<Vec<FlagCalledEventParams>>,
}

impl FeatureFlagEvaluationsHost for RecordingHost {
    fn capture_flag_called_event_if_needed(&self, params: FlagCalledEventParams) {
        self.captured.lock().unwrap().push(params);
    }
    fn log_warning(&self, _message: &str) {}
}

/// A flag that evaluates locally to `true` (active, 100% rollout, no property
/// filters), carrying the given experiment signal.
fn gated_flag(has_experiment: Option<bool>) -> FeatureFlag {
    FeatureFlag {
        key: "gated".into(),
        active: true,
        has_experiment,
        filters: FeatureFlagFilters {
            groups: vec![FeatureFlagCondition {
                properties: vec![],
                rollout_percentage: Some(100.0),
                variant: None,
                aggregation_group_type_index: None,
            }],
            multivariate: None,
            payloads: HashMap::new(),
            aggregation_group_type_index: None,
            early_exit: false,
        },
    }
}

pub(super) fn definitions(has_experiment: Option<bool>, gate: bool) -> LocalEvaluationResponse {
    LocalEvaluationResponse {
        property_matching_version: 1,
        flags: vec![gated_flag(has_experiment)],
        group_type_mapping: HashMap::new(),
        cohorts: HashMap::new(),
        minimal_flag_called_events: gate,
    }
}

#![cfg(all(not(feature = "async-client"), not(feature = "capture-v1")))]

//! V0 retry behavior (blocking client) under the background transport. `capture`
//! is a non-blocking enqueue, so these tests drive delivery with `flush()` (each
//! flush makes one attempt per pending batch, ignoring backoff). Exhausting the
//! attempt budget takes `max_attempts` flushes; the Retry-After test instead
//! lets the worker retry on its own schedule so the header delay is observable.

use std::io::Read;
use std::time::{Duration, Instant};

use httpmock::prelude::*;
use posthog_rs::{CaptureCompression, Client, ClientOptionsBuilder, Event};

// A real v7 UUID so the event passes through unchanged; matched on the wire to
// prove retried attempts resend the same bytes.
const FIXED_UUID: &str = "01920000-0000-7000-8000-0000000000ff";

fn create_v0_client(base_url: String, max_attempts: u32) -> Client {
    let options = ClientOptionsBuilder::default()
        .api_key("phc_test_token".to_string())
        .host(base_url)
        .max_capture_attempts(max_attempts)
        // Tiny initial backoff keeps retries fast; max kept above the 1s
        // Retry-After the retry-after test asserts (Retry-After is clamped to it).
        .retry_initial_backoff_ms(1u64)
        .retry_max_backoff_ms(2000u64)
        .build()
        .unwrap();
    posthog_rs::client(options)
}

/// Drive whichever capture entry point the test wants. Both now enqueue onto the
/// same worker and send through `/batch/`.
fn capture(client: &Client, batch: bool) {
    if batch {
        client.capture_batch(vec![Event::new("e", "user-1")], false);
    } else {
        client.capture(Event::new("e", "user-1"));
    }
}

/// Poll until a mock has been hit `want` times (for the autonomous retry path
/// that isn't driven by `flush()`).
fn wait_for_hits(mock: &httpmock::Mock, want: usize) {
    for _ in 0..400 {
        if mock.hits() >= want {
            return;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(mock.hits(), want, "timed out waiting for {want} hits");
}

#[test]
fn retryable_status_keeps_retrying_until_attempts_exhausted() {
    for status in [408u16, 500, 502, 503, 504] {
        for batch in [false, true] {
            let server = MockServer::start();
            let mock = server.mock(|when, then| {
                when.method(POST);
                then.status(status);
            });

            let client = create_v0_client(server.base_url(), 3);
            capture(&client, batch);
            client.flush();
            client.flush();
            client.flush();

            mock.assert_hits(3);

            // Budget exhausted: the event is dropped, so a further flush is a no-op.
            client.flush();
            mock.assert_hits(3);
        }
    }
}

#[test]
fn terminal_status_sends_once() {
    // 429 here carries no Retry-After, so it is terminal, not retried — see
    // `honors_retry_after_header` for the 429 + Retry-After case.
    for status in [400u16, 401, 402, 403, 413, 415, 429] {
        for batch in [false, true] {
            let server = MockServer::start();
            let mock = server.mock(|when, then| {
                when.method(POST);
                then.status(status);
            });

            let client = create_v0_client(server.base_url(), 3);
            capture(&client, batch);
            client.flush();
            mock.assert_hits(1);

            // Terminal: dropped, not retried.
            client.flush();
            mock.assert_hits(1);
        }
    }
}

#[test]
fn success_sends_once() {
    for batch in [false, true] {
        let server = MockServer::start();
        let mock = server.mock(|when, then| {
            when.method(POST);
            then.status(200);
        });

        let client = create_v0_client(server.base_url(), 3);
        capture(&client, batch);
        client.flush();
        mock.assert_hits(1);
    }
}

#[test]
fn retries_resend_identical_event() {
    let server = MockServer::start();
    // The mock only matches requests carrying the original UUID, so reaching
    // 3 hits proves every retry resent the same event identity.
    let mock = server.mock(|when, then| {
        when.method(POST).body_includes(FIXED_UUID);
        then.status(503);
    });

    let client = create_v0_client(server.base_url(), 3);
    let mut event = Event::new("e", "user-1");
    event.set_uuid(uuid::Uuid::parse_str(FIXED_UUID).unwrap());
    client.capture(event);
    client.flush();
    client.flush();
    client.flush();

    mock.assert_hits(3);
}

/// Matcher: the request body is valid gzip that decodes to the expected event.
fn body_gunzips_to_user1(req: &HttpMockRequest) -> bool {
    let mut decoder = flate2::read::GzDecoder::new(req.body_ref());
    let mut decoded = String::new();
    match decoder.read_to_string(&mut decoded) {
        Ok(_) => decoded.contains(r#""distinct_id":"user1""#),
        Err(_) => false,
    }
}

#[test]
fn gzip_sets_header_query_param_and_compresses_body() {
    let server = MockServer::start();
    let mock = server.mock(|when, then| {
        when.method(POST)
            .header("content-encoding", "gzip")
            .query_param("compression", "gzip")
            .matches(body_gunzips_to_user1);
        then.status(200);
    });

    let options = ClientOptionsBuilder::default()
        .api_key("phc_test_token".to_string())
        .host(server.base_url())
        .capture_compression(CaptureCompression::Gzip)
        .build()
        .unwrap();
    let client = posthog_rs::client(options);
    client.capture(Event::new("test_event", "user1"));
    client.flush();

    mock.assert();
}

#[test]
fn honors_retry_after_header() {
    let server = MockServer::start();
    // A 429 carrying Retry-After must delay the resend by the header value.
    // `flush()` forces an immediate attempt and would bypass the backoff, so we
    // let the worker retry on its own schedule and observe the gap.
    let mock = server.mock(|when, then| {
        when.method(POST);
        then.status(429).header("retry-after", "1");
    });

    let client = create_v0_client(server.base_url(), 2);
    client.capture(Event::new("e", "user-1"));

    let start = Instant::now();
    client.flush();
    mock.assert_hits(1);
    wait_for_hits(&mock, 2);
    let elapsed = start.elapsed();

    mock.assert_hits(2);
    assert!(
        elapsed >= Duration::from_millis(900),
        "Retry-After header not honored: second attempt after only {:?}",
        elapsed
    );
}

//! Shared fixtures for the local-evaluation payload tests in `async_client`
//! and `blocking`. Those two modules are mutually exclusive under the
//! `async-client` feature, so this lives outside both to avoid two copies
//! drifting out of sync.

use std::collections::HashMap;

use serde_json::json;

use crate::feature_flags::{
    FeatureFlag, FeatureFlagCondition, FeatureFlagFilters, MultivariateFilter, MultivariateVariant,
};
use crate::local_evaluation::LocalEvaluationResponse;

fn flag(
    key: &str,
    rollout_percentage: f64,
    multivariate: Option<MultivariateFilter>,
    payloads: &[(&str, serde_json::Value)],
) -> FeatureFlag {
    FeatureFlag {
        key: key.into(),
        active: true,
        has_experiment: None,
        filters: FeatureFlagFilters {
            groups: vec![FeatureFlagCondition {
                properties: vec![],
                rollout_percentage: Some(rollout_percentage),
                variant: None,
                aggregation_group_type_index: None,
            }],
            multivariate,
            payloads: payloads
                .iter()
                .map(|(key, payload)| ((*key).to_string(), payload.clone()))
                .collect(),
            aggregation_group_type_index: None,
            early_exit: false,
        },
    }
}

/// Definitions covering every shape a payload can take in the manifest, all
/// evaluable without person properties.
pub(super) fn payload_definitions() -> LocalEvaluationResponse {
    let variants = MultivariateFilter {
        variants: vec![
            MultivariateVariant {
                key: "test".into(),
                rollout_percentage: 100.0,
            },
            MultivariateVariant {
                key: "control".into(),
                rollout_percentage: 0.0,
            },
        ],
    };

    LocalEvaluationResponse {
        property_matching_version: 1,
        flags: vec![
            // The definitions endpoint JSON-encodes payloads, so the common
            // case is an object stored as a string.
            flag(
                "json-string-payload",
                100.0,
                None,
                &[("true", json!("{\"color\": \"blue\"}"))],
            ),
            // Definitions written before payloads were normalised server-side
            // can still carry an already-parsed value.
            flag(
                "parsed-payload",
                100.0,
                None,
                &[("true", json!({"color": "blue"}))],
            ),
            // A string payload is stored double-encoded.
            flag(
                "quoted-string-payload",
                100.0,
                None,
                &[("true", json!("\"just text\""))],
            ),
            // Not valid JSON: the raw string survives rather than erroring.
            flag(
                "undecodable-payload",
                100.0,
                None,
                &[("true", json!("not json"))],
            ),
            // Keyed by variant, so the wrong variant's payload must not leak.
            flag(
                "variant-payload",
                100.0,
                Some(variants),
                &[
                    ("test", json!("{\"tier\": 2}")),
                    ("control", json!("{\"tier\": 1}")),
                ],
            ),
            flag("no-payload", 100.0, None, &[]),
            // Evaluates false, so `/flags` would report no payload either.
            flag(
                "disabled-with-payload",
                0.0,
                None,
                &[("true", json!("{\"unreachable\": true}"))],
            ),
        ],
        group_type_mapping: HashMap::new(),
        cohorts: HashMap::new(),
        minimal_flag_called_events: false,
    }
}

