//! One test owns the process-wide singleton; other global scenarios use separate binaries.
use httpmock::prelude::*;
use posthog_rs::{ClientOptionsBuilder, Error, Event};
use serde_json::{json, Value};

#[cfg(feature = "async-client")]
macro_rules! call {
    ($expr:expr) => {
        futures::executor::block_on($expr)
    };
}
#[cfg(not(feature = "async-client"))]
macro_rules! call {
    ($expr:expr) => {
        $expr
    };
}

#[test]
fn global_client_lifecycle() {
    let server = MockServer::start();
    let capture = server.mock(|when, then| {
        when.method(POST).matches(|request| {
            let body: Value = serde_json::from_slice(request.body_ref()).unwrap();
            body["batch"].as_array().is_some_and(|batch| {
                batch.len() == 1
                    && batch[0]["event"] == "global-event"
                    && batch[0]["distinct_id"] == "user-1"
            })
        });
        then.status(200).json_body(json!({"results": {}}));
    });
    let options = ClientOptionsBuilder::default()
        .api_key("phc_test".to_string())
        .host(server.base_url())
        .flush_interval_ms(600_000)
        .build()
        .unwrap();

    assert!(!posthog_rs::global_is_disabled());
    posthog_rs::capture(Event::new("before-init", "user-1"));
    call!(posthog_rs::flush());
    call!(posthog_rs::shutdown());
    #[cfg(feature = "error-tracking")]
    {
        let error = std::io::Error::other("global error");
        assert!(matches!(
            call!(posthog_rs::capture_exception(&error)),
            Err(Error::NotInitialized)
        ));
        assert!(matches!(
            call!(posthog_rs::capture_exception_with(
                &error,
                posthog_rs::CaptureExceptionOptions::new()
            )),
            Err(Error::NotInitialized)
        ));
    }
    capture.assert_calls(0);

    call!(posthog_rs::init_global(options.clone())).unwrap();
    assert!(matches!(
        call!(posthog_rs::init_global(options)),
        Err(Error::AlreadyInitialized)
    ));
    posthog_rs::capture(Event::new("global-event", "user-1"));
    call!(posthog_rs::flush());
    capture.assert_calls(1);

    posthog_rs::disable_global();
    assert!(posthog_rs::global_is_disabled());
    posthog_rs::capture(Event::new("global-event", "user-1"));
    call!(posthog_rs::flush());
    capture.assert_calls(2);

    #[cfg(feature = "error-tracking")]
    {
        let exceptions = server.mock(|when, then| {
            when.method(POST).matches(|request| {
                let body: Value = serde_json::from_slice(request.body_ref()).unwrap();
                let batch = body["batch"].as_array().unwrap();
                batch.len() == 2
                    && batch.iter().all(|event| event["event"] == "$exception")
                    && batch[1]["distinct_id"] == "identified-user"
                    && batch[1]["properties"]["context"] == "global"
            });
            then.status(200).json_body(json!({"results": {}}));
        });
        let error = std::io::Error::other("global error");
        call!(posthog_rs::capture_exception(&error)).unwrap();
        call!(posthog_rs::capture_exception_with(
            &error,
            posthog_rs::CaptureExceptionOptions::new()
                .distinct_id("identified-user")
                .property("context", "global")
                .unwrap()
        ))
        .unwrap();
        call!(posthog_rs::flush());
        exceptions.assert_calls(1);
    }

    posthog_rs::capture(Event::new("global-event", "user-1"));
    call!(posthog_rs::shutdown());
    capture.assert_calls(3);
    posthog_rs::capture(Event::new("global-event", "user-1"));
    call!(posthog_rs::flush());
    call!(posthog_rs::shutdown());
    capture.assert_calls(3);
}

//! End-to-end check that `init_global` installs panic autocapture when
//! `capture_panics` is enabled.
//!
//! This lives in its own integration-test binary on purpose: it initializes the
//! real process-wide global client (a set-once `OnceLock`) and installs the
//! process-wide panic hook. Its own process gives it a fresh `OnceLock`, so it
//! is isolated — the equivalent in-process unit test would be order-dependent
//! (the `OnceLock` can't be reset) and break as soon as another test touched the
//! global. The gate logic and the hook mechanism are covered by the in-process
//! unit tests; this only exercises the `init_global` -> hook wiring.
#![cfg(feature = "error-tracking")]

use httpmock::prelude::*;
use std::panic::{self, AssertUnwindSafe};

/// The panic site, named so the captured stack frame is matchable. Lives in
/// this test crate (not `posthog_rs`), so its frame classifies as in-app —
/// which the in-process unit tests can't show (a panic there originates inside
/// `posthog_rs`, which is classified out-of-app).
#[inline(never)]
fn integration_panic_site() {
    panic!("integration panic boom");
}

/// True when the request body carries a personless panic `$exception` event in
/// the transport's batch envelope (same shape for the V0 and V1 wire formats),
/// the user's panic-site frame is kept and marked `in_app = true`, and the
/// frames obey the canonical wire order (outermost first, crash site last) with
/// the SDK's own capture plumbing stripped from the crash-site tail.
fn is_panic_exception(req: &HttpMockRequest) -> bool {
    let Ok(body) = serde_json::from_slice::<serde_json::Value>(req.body_ref()) else {
        return false;
    };
    let is_panic = body.pointer("/batch/0/event").and_then(|v| v.as_str()) == Some("$exception")
        && body
            .pointer("/batch/0/properties/$exception_list/0/type")
            .and_then(|v| v.as_str())
            == Some("Panic");
    let Some(frames) = body
        .pointer("/batch/0/properties/$exception_list/0/stacktrace/frames")
        .and_then(|v| v.as_array())
    else {
        return false;
    };
    let function_names: Vec<&str> = frames
        .iter()
        .map(|frame| frame["function"].as_str().unwrap_or_default())
        .collect();
    let panic_site_in_app = frames.iter().any(|frame| {
        frame["function"]
            .as_str()
            .is_some_and(|name| name.contains("integration_panic_site"))
            && frame["in_app"] == true
    });
    // Canonical wire order puts the crash site last. The panic hook fires nested
    // inside the panic runtime, so a naive reverse would leave the SDK's own hook
    // plumbing (`posthog_rs::error_tracking::*`) as the tail. We strip everything
    // innermost of the panic dispatcher, so no posthog_rs frame survives at all,
    // and the tail is the crash-side panic runtime rather than an SDK frame.
    let no_sdk_frames = !function_names
        .iter()
        .any(|name| name.contains("posthog_rs::error_tracking"));
    let tail_is_panic_runtime = function_names
        .last()
        .is_some_and(|name| name.contains("panicking::") || name.contains("panic_with_hook"));
    // The user's panic site must come *before* (outermore than) the crash-side
    // panic runtime that follows it — i.e. it is not left innermost/first.
    let panic_site_before_runtime = function_names
        .iter()
        .position(|name| name.contains("integration_panic_site"))
        .zip(
            function_names
                .iter()
                .rposition(|name| name.contains("panic_with_hook")),
        )
        .is_some_and(|(site, runtime)| site < runtime);
    is_panic
        && panic_site_in_app
        && no_sdk_frames
        && tail_is_panic_runtime
        && panic_site_before_runtime
}

#[cfg(feature = "async-client")]
fn init_global_for_test(options: posthog_rs::ClientOptions) -> Result<(), posthog_rs::Error> {
    // The async constructor only awaits under local evaluation, so a minimal
    // executor drives it with no Tokio runtime needed.
    futures::executor::block_on(posthog_rs::init_global(options))
}

#[cfg(not(feature = "async-client"))]
fn init_global_for_test(options: posthog_rs::ClientOptions) -> Result<(), posthog_rs::Error> {
    posthog_rs::init_global(options)
}

#[test]
fn init_global_installs_panic_capture_when_enabled() {
    let server = MockServer::start();
    let mock = server.mock(|when, then| {
        when.method(POST).matches(is_panic_exception);
        then.status(200);
    });

    // Quiet the default hook (init_global chains whatever is installed now) so a
    // caught, expected panic doesn't print to the test output.
    panic::set_hook(Box::new(|_| {}));

    let options = posthog_rs::ClientOptionsBuilder::default()
        .api_key("test_api_key".to_string())
        .host(server.base_url())
        .error_tracking(
            posthog_rs::ErrorTrackingOptionsBuilder::default()
                .capture_panics(true)
                .build()
                .unwrap(),
        )
        .build()
        .unwrap();
    init_global_for_test(options).expect("init_global should succeed");

    // With `capture_panics` enabled, the installed hook routes this panic through
    // the global client. `catch_unwind` keeps the test process alive; the hook's
    // flush is synchronous, so the event has been sent by the time it returns.
    let _ = panic::catch_unwind(AssertUnwindSafe(integration_panic_site));

    mock.assert_hits(1);
}

//! Exercise real TLS initialization failures through the public constructors.
//! Linux uses SSL_CERT_FILE / SSL_CERT_DIR for its platform trust store.
#![cfg(target_os = "linux")]

use std::process::{Command, Stdio};
use std::time::{Duration, Instant};

use httpmock::prelude::*;
use posthog_rs::{
    ClientOptionsBuilder, Error, Event, FlagCache, FlagPoller, LocalEvaluationConfig,
};

/// Isolate the empty trust store in a subprocess so parallel tests keep their
/// normal certificates. The mock server stays in the parent for the same reason.
fn without_ca_certificates(test_name: &str, test: impl FnOnce(String)) {
    if std::env::var("POSTHOG_RS_EMPTY_CA_TEST").as_deref() == Ok(test_name) {
        let error = reqwest::Client::builder()
            .build()
            .expect_err("the empty trust store must cause an HTTP builder error");
        assert!(format!("{error:?}").contains("No CA certificates were loaded"));
        tracing_subscriber::fmt()
            .with_ansi(false)
            .with_max_level(tracing::Level::WARN)
            .with_writer(std::io::stderr)
            .init();
        test(std::env::var("POSTHOG_RS_EMPTY_CA_HOST").expect("parent mock server URL"));
        return;
    }

    let server = MockServer::start();
    let requests = server.mock(|_when, then| {
        then.status(200).json_body(serde_json::json!({}));
    });
    let empty_dir = std::env::temp_dir().join(format!("posthog-empty-ca-{}", uuid::Uuid::now_v7()));
    std::fs::create_dir(&empty_dir).expect("create empty certificate directory");
    let mut child = Command::new(std::env::current_exe().expect("integration test executable"))
        .args(["--exact", test_name, "--nocapture"])
        .env("POSTHOG_RS_EMPTY_CA_TEST", test_name)
        .env("POSTHOG_RS_EMPTY_CA_HOST", server.base_url())
        .env("SSL_CERT_FILE", "/dev/null")
        .env("SSL_CERT_DIR", &empty_dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("start empty-trust-store subprocess");

    let deadline = Instant::now() + Duration::from_secs(30);
    while child.try_wait().expect("check subprocess status").is_none() {
        if Instant::now() >= deadline {
            child.kill().expect("terminate stalled subprocess");
            break;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
    let output = child.wait_with_output().expect("collect subprocess output");
    std::fs::remove_dir(&empty_dir).expect("remove certificate directory");
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success(),
        "empty-trust-store subprocess failed: {}\n{}\n{stderr}",
        output.status,
        String::from_utf8_lossy(&output.stdout),
    );
    assert!(
        stderr.contains("No CA certificates were loaded"),
        "warning must include the builder error's cause: {}",
        stderr,
    );
    requests.assert_calls(0);
}

#[cfg(feature = "async-client")]
fn complete<T>(operation: impl std::future::Future<Output = T>) -> T {
    futures::executor::block_on(operation)
}

#[cfg(not(feature = "async-client"))]
fn complete<T>(result: T) -> T {
    result
}

#[test]
fn client_without_ca_certificates_is_noop() {
    without_ca_certificates("client_without_ca_certificates_is_noop", |host| {
        for local_evaluation in [false, true] {
            let options = ClientOptionsBuilder::default()
                .api_key("phc_test".to_string())
                .secret_key("phx_test")
                .host(host.clone())
                .enable_local_evaluation(local_evaluation)
                .request_timeout_seconds(1u64)
                .build()
                .expect("valid client options");
            assert!(!options.is_disabled());
            let client = complete(posthog_rs::client(options));
            let event = Event::new("test_event", "test_user");
            client.capture(event.clone());
            client.capture_batch(vec![event.clone()], false);
            client.capture_batch(vec![event.clone()], true);
            let summary = complete(client.capture_immediate(event))
                .expect("disabled capture should succeed without sending");
            assert_eq!(summary.submitted(), 0);

            let (flags, payloads) =
                complete(client.get_feature_flags("test_user".to_string(), None, None, None))
                    .expect("disabled flags should return empty results");
            assert!(flags.is_empty());
            assert!(payloads.is_empty());
            #[allow(deprecated)]
            let payload = complete(client.get_feature_flag_payload("test_flag", "test_user"))
                .expect("disabled payload request should succeed");
            assert_eq!(payload, None);
            let evaluations = complete(client.evaluate_flags("test_user", Default::default()))
                .expect("disabled evaluation should succeed");
            assert_eq!(evaluations.get_flag("test_flag"), None);

            complete(client.flush());
            complete(client.shutdown());
            complete(client.shutdown());
        }
    });
}

fn poller_config(host: String) -> LocalEvaluationConfig {
    LocalEvaluationConfig {
        personal_api_key: "phx_test".to_string(),
        project_api_key: "phc_test".to_string(),
        api_host: host,
        poll_interval: Duration::from_secs(30),
        request_timeout: Duration::from_secs(1),
    }
}

#[test]
fn blocking_poller_without_ca_certificates_stays_stopped() {
    without_ca_certificates(
        "blocking_poller_without_ca_certificates_stays_stopped",
        |host| {
            let mut poller = FlagPoller::new(poller_config(host), FlagCache::new());
            assert!(matches!(poller.load_flags(), Err(Error::Connection(_))));
            poller.start();
            poller.stop();
        },
    );
}

#[cfg(feature = "async-client")]
#[test]
fn async_poller_without_ca_certificates_stays_stopped() {
    without_ca_certificates(
        "async_poller_without_ca_certificates_stays_stopped",
        |host| {
            let mut poller =
                posthog_rs::AsyncFlagPoller::new(poller_config(host), FlagCache::new());
            assert!(matches!(
                complete(poller.load_flags()),
                Err(Error::Connection(_))
            ));
            complete(poller.start());
            assert!(!complete(poller.is_running()));
            complete(poller.stop());
        },
    );
}
